def maxUniqueSplits(s):
    n = len(s)
    best = 0
    seen = set()

    def go(i, cnt):
        nonlocal best
        if cnt + (n - i) <= best:
            return
        if i == n:
            best = cnt
            return
        for j in range(i + 1, n + 1):
            piece = s[i:j]
            if piece not in seen:
                seen.add(piece)
                go(j, cnt + 1)
                seen.remove(piece)

    go(0, 0)
    return best
